"""Explicit, dimensioned Pepper's Ghost reflector project, not free-air holography."""
import math
from .workshop import DEFAULT
from .workshop_free import result

def design(body):
 if not isinstance(body,dict)or set(body)-{'base','opening'}:raise ValueError('Nur äußere Breite und kleine Öffnung angeben.')
 base=body.get('base',60);opening=body.get('opening',10)
 if any(type(n)not in {float,int}or not math.isfinite(n)for n in [base,opening])or not 40<=base<=160 or not 4<=opening<=30 or opening>=base*.6:raise ValueError('Außenbreite 40–160 mm; kleine Öffnung 4–30 mm und kleiner als 60 % der Außenbreite.')
 rise=(base-opening)/2;slant=math.hypot(rise,rise);offset=(base+opening)/4
 parts=[]
 for name,pos,rot in [('Vorderseite',[0,rise/2,offset],[45,0,0]),('Rückseite',[0,rise/2,-offset],[-45,0,0]),('Rechte Seite',[offset,rise/2,0],[90,45,-90]),('Linke Seite',[-offset,rise/2,0],[90,-45,90])]:
  parts.append({'name':name,'shape':'extrude','size':[base,slant,.5],'position':pos,'rotation':rot,'material':'plastic','outline':[[-opening/base/2,-.5],[opening/base/2,-.5],[.5,.5],[-.5,.5]]})
 data=result({'title':'Smartphone-Reflektor · Pepper’s Ghost','parts':parts,'features':['Vier transparente Flächen spiegeln ein Motiv vom Smartphone-Display.','Ein schwebend wirkendes Bild im Inneren; keine Projektion frei in den Raum.'],'explanation':'Hier baust du ein echtes kleines optisches Demonstrationsgerät: vier klare Trapeze stehen bei 45° um eine kleine Öffnung. Das Display darunter liefert das Bild. Die Wirkung ist eine Spiegelungsillusion, die oft Hologramm genannt wird.','steps':['Prüfe, ob dein Smartphone-Display mindestens '+str(base)+' mm nutzbare Breite hat; der große Rand darf nicht überstehen.','Zeichne vier gleiche Trapeze: große Kante '+str(base)+' mm, kleine Kante '+str(opening)+' mm, senkrechter Abstand auf der flachen Folie '+str(round(slant,1))+' mm. Zuerst Papiermuster falten und die Passung prüfen.','Schneide die vier Teile aus klarer PET-Folie und verbinde die Seitenkanten vorsichtig mit transparentem Klebeband. Die schmalen Kanten bilden unten die kleine quadratische Öffnung. Bei scharfen Werkzeugen Hilfe holen.','Lege eine saubere Schutzfolie aufs Display. Stelle den Reflektor mittig mit der kleinen Öffnung nach unten auf. Keine scharfen Kanten auf das Glas setzen.','Öffne das vierfache Testmotiv, stelle die Displayhelligkeit passend ein und dunkle den Raum ab. Das Motiv wird an den schrägen Flächen gespiegelt.']},{**DEFAULT,'material':'plastic'})
 data['supplies']=[{'name':p['name'],'size':p['size'],'material':'Klare ungetönte PET-Folie, etwa 0,5 mm'}for p in data['parts']]
 data['tools']=['Lineal, Papiermuster, geeignete Schere, transparentes Klebeband, Displayschutz.'];data['decisions']=['Konkretes bereitgestelltes Bauprojekt mit geometrisch berechneten Maßen; keine neu erfundene KI-Konstruktion.','45° Flächenneigung; senkrechte Gerätehöhe '+str(round(rise,1))+' mm.','Vor dem Zuschneiden Papiermuster und tatsächliche Displaygröße prüfen.'];data['limits']='Optisches Demonstrationsprojekt. Keine frei schwebende volumetrische Projektion. Bildqualität hängt von Folie, Display, Motiv und Raumlicht ab; nicht auf deiner Hardware getestet.';data['brief']='Smartphone-Reflektor bauen';data['project_kind']='phone_reflector';data['project_dimensions']={'base':base,'opening':opening};data['reply']='Sir, hier ist ein konkretes Bauprojekt mit vier Teilen, Zuschnittmaßen, Materialliste und Anleitung. Öffne „Anleitung direkt ansehen“ und das vierfache Testmotiv.';return data
